    private const val DARK_DEFAULT = 379
    private const val LIGHT_DEFAULT = 380

    fun forFile(name: String, light: Boolean): Glyph {
        val names = if (light) LIGHT_NAMES else DARK_NAMES
        val exts = if (light) LIGHT_EXTS else DARK_EXTS
        val lower = name.lowercase()
        val index = names[lower]
            ?: extensionsOf(lower).firstNotNullOfOrNull { exts[it] }
            ?: if (light) LIGHT_DEFAULT else DARK_DEFAULT
        return Glyph(CHARS[index], COLOURS[index])
    }

    /** `a.spec.ts` -> `spec.ts`, `ts`; a leading dot is part of the name (`.gitignore` -> `gitignore`). */
    private fun extensionsOf(name: String): Sequence<String> = sequence {
        var dot = name.indexOf('.')
        while (dot >= 0 && dot < name.length - 1) {
            yield(name.substring(dot + 1))
            dot = name.indexOf('.', dot + 1)
        }
    }

    private fun parse(table: String): Map<String, Int> {
        val map = HashMap<String, Int>(table.length / 8)
        for (entry in table.split(';')) {
            val eq = entry.lastIndexOf('=')
            if (eq > 0) map[entry.substring(0, eq)] = entry.substring(eq + 1).toInt()
        }
        return map
    }
